          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["id", "detect", "resumeArgvPrefix"],
            "not": { "required": ["kind", "kinds"] },
            "properties": {
              "id": {
                "type": "string",
                "pattern": "^[A-Za-z0-9._-]+$",
                "description": "Stable identifier recorded on the launch capture, for example teamclaude."
              },
              "kind": {
                "type": "string",
                "pattern": "\\S",
                "description": "Single built-in agent kind this launcher wraps, for example claude. Omit the key entirely to match every kind; an empty or blank value makes the declaration unusable rather than widening it."
              },
              "kinds": {
                "type": "array",
                "minItems": 1,
                "items": { "type": "string", "pattern": "\\S" },
                "description": "Built-in agent kinds this launcher wraps, for example [\"claude\"]. Omit the key entirely to match every kind; an empty array makes the declaration unusable rather than widening it."
              },
              "detect": {
                "type": "object",
                "additionalProperties": false,
                "required": ["argvExecutables"],
                "description": "How the launcher process is recognized among an agent's ancestors.",
                "properties": {
                  "argvExecutables": {
                    "oneOf": [
                      { "type": "string", "pattern": "\\S" },
                      { "type": "array", "minItems": 1, "items": { "type": "string", "pattern": "\\S" } }
                    ],
                    "description": "Executable names or paths identifying the launcher, for example [\"teamclaude\"]. A match requires the executable of an ancestor process — or its last path component — to equal an entry exactly; substrings never match, so an unrelated path containing the name cannot claim the session. Env prefixes, package runners, and interpreters are followed (env VAR=1 llm-gateway exec, node /usr/local/bin/teamclaude run), up to two levels; after an interpreter the search stops at its first option, since those decide what the program is."
                  }
                }
              },
              "resumeArgvPrefix": {
                "type": "array",
                "minItems": 1,
                "items": { "type": "string", "pattern": "\\S" },
