          "type": "boolean",
          "default": false,
          "description": "When cmux is inactive, the first click can activate and focus the clicked pane."
        },
        "paneResizeStepPixels": {
          "type": "integer",
          "minimum": 1,
          "maximum": 200,
          "default": 20,
          "description": "Pixels moved per keypress when using pane-resize shortcuts.",
          "descriptionKey": "schemaDescriptions.app.paneResizeStepPixels"
        },
        "focusHistoryIncludesPanesAndTabs": {
          "type": "boolean",
          "default": false,
          "description": "When true, Back and Forward include focus changes between panes and tabs. When false, they navigate between workspaces only."
        },
        "equalizeSplitsOnCreate": {
          "type": "boolean",
          "default": false,
          "description": "When true, creating a split resizes the panes in that split's row or column to equal sizes. When false, a new split halves the pane it was created from."
        },
        "preferredEditor": {
          "type": "string",
          "default": "",
          "description": "Custom editor command used when Cmd-click file previews are disabled or a file is unsupported. Leave empty to use the default."
        },
        "defaultWorkspacePath": {
          "type": "string",
          "default": "",
          "description": "Folder the Open Folder panel starts in, for example ~/code. Supports a leading ~. Leave empty to start in the active workspace's directory."
        },
        "openSupportedFilesInCmux": {
          "type": "boolean",
          "default": true,
          "description": "When enabled, Cmd-clicking readable local files opens supported previews in cmux, including text, code, PDFs, images, audio, video, and Quick Look files. Preview headers include an Open With menu based on the user's default and compatible macOS apps for that file."
        },
        "openMarkdownInCmuxViewer": {
          "type": "boolean",
          "default": true,
          "description": "When enabled, Cmd-clicking .md/.markdown/.mkd/.mdx files opens the rendered cmux markdown viewer panel (with live reload) instead of the generic file preview."
        },
        "globalFontMagnification": {
          "type": "integer",
          "minimum": 50,
          "maximum": 200,
          "multipleOf": 10,
          "default": 100,
          "descriptionKey": "schemaDescriptions.app.globalFontMagnification",
          "description": "Scales cmux-owned terminals, tab titles, sidebars, settings, overlays, and app chrome by this percentage. Rendered browser page content is excluded."
        },
        "reorderOnNotification": {
          "oneOf": [
            {
              "type": "boolean"
            },
            {
              "type": "string",
              "enum": ["off", "notifications", "agentActivity"]
            }
          ],
          "default": true,
          "description": "Automatic workspace reordering. true or \"notifications\" moves workspaces with new notifications toward the top. \"agentActivity\" also moves them when a prompt is sent or an agent finishes a turn, needs input, or fails, at most once per burst and never while the pointer is over the sidebar. false or \"off\" keeps the order stable."
        },
        "iMessageMode": {
          "type": "boolean",
          "default": false,
          "description": "Move a workspace to the top and show the submitted message when sending an agent prompt."
        },
        "sendAnonymousTelemetry": {
          "type": "boolean",
          "default": true,
          "description": "Allow anonymous telemetry."
        },
        "confirmQuit": {
          "type": "string",
          "enum": ["always", "dirty-only", "never"],
          "default": "always",
          "descriptionKey": "schemaDescriptions.app.confirmQuit",
          "description": "Control when cmux asks for confirmation before quitting. DEV builds always quit immediately regardless of this setting. Legacy app.warnBeforeQuit is still accepted as a boolean fallback."
        },
        "warnBeforeQuit": {
          "type": "boolean",
          "default": true,
          "descriptionKey": "schemaDescriptions.app.warnBeforeQuit",
          "description": "Legacy boolean fallback for quit confirmation. Use app.confirmQuit for new configs."
        },
        "warnBeforeClosingTab": {
          "type": "boolean",
          "default": true,
          "description": "Show a confirmation before closing a tab."
        },
        "warnBeforeClosingTabXButton": {
          "type": "boolean",
          "default": false,
          "descriptionKey": "schemaDescriptions.app.warnBeforeClosingTabXButton",
          "description": "Show a confirmation before closing a tab with the tab close button."
        },
        "warnBeforeClosingWorkspace": {
          "type": "boolean",
          "default": true,
          "description": "Show a confirmation before closing a workspace with a running process, or several workspaces at once. Pinned workspaces still ask when this is off."
        },
        "warnBeforeClosingWindow": {
          "type": "boolean",
          "default": true,
          "description": "Show a confirmation before closing a window with a running process, or all of a window's workspaces at once."
        },
        "hideTabCloseButton": {
          "type": "boolean",
          "default": false,
          "descriptionKey": "schemaDescriptions.app.hideTabCloseButton",
          "description": "Hide tab close buttons in the pane tab bar."
        },
        "tabBarVisibility": {
          "type": "string",
          "enum": ["always", "multiple-tabs"],
          "default": "always",
          "descriptionKey": "schemaDescriptions.app.tabBarVisibility",
          "description": "Decide when a pane draws its tab bar. \"always\" draws it even for a pane holding one tab; \"multiple-tabs\" hides it while a pane holds one tab and draws it once a second tab opens. Minimal mode (app.minimalMode) always draws it, because there the top pane's tab bar doubles as the window titlebar."
        },
        "renameSelectsExistingName": {
          "type": "boolean",
          "default": true,
          "description": "Select the current name when opening rename flows."
        },
        "commandPaletteSearchesAllSurfaces": {
          "type": "boolean",
          "default": false,
          "description": "Search every surface in the command palette switcher instead of only the active workspace."
        }
      }
    },
    "terminal": {
      "x-cmux-scopes": ["global"],
      "title": "terminal",
      "description": "Terminal presentation settings from Settings > Terminal.",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "adaptiveDefaultTheme": {
          "type": "boolean",
          "default": true,
          "descriptionKey": "schemaDescriptions.terminal.adaptiveDefaultTheme",
          "description": "When true (the default), cmux supplies an appearance-adaptive default palette unless a Ghostty theme or terminal colors are configured. Font and other settings are preserved. When false, Ghostty uses its fixed built-in palette. Explicit themes and colors always take precedence, including theme = light:X,dark:Y."
        },
        "showScrollBar": {
          "type": "boolean",
          "default": true,
          "description": "Show the right-edge terminal scroll bar when scrollback is available. cmux automatically suppresses it for alternate-screen style TUI surfaces."
        },
        "scrollSpeed": {
          "type": "number",
          "minimum": 0.25,
          "maximum": 3.0,
          "default": 1.0,
          "descriptionKey": "schemaDescriptions.terminal.scrollSpeed",
          "description": "Multiplier applied to terminal scroll wheel and trackpad deltas. Higher values scroll faster; lower values scroll slower."
        },
        "sessionContentMaxWidth": {
          "oneOf": [
            {
              "type": "boolean",
              "const": false
            },
            {
              "type": "number",
              "minimum": 320,
              "multipleOf": 20
            }
          ],
          "default": false,
          "descriptionKey": "schemaDescriptions.terminal.sessionContentMaxWidth",
          "description": "Optional maximum width, in points, for terminal and built-in agent chat content. Set false to use the full pane width."
        },
        "sessionContentAlignment": {
          "type": "string",
          "enum": ["left", "center", "right"],
          "default": "center",
          "descriptionKey": "schemaDescriptions.terminal.sessionContentAlignment",
          "description": "Horizontal placement for terminal and built-in agent chat content when sessionContentMaxWidth is enabled."
        },
        "copyOnSelect": {
          "type": "boolean",
          "default": false,
          "descriptionKey": "schemaDescriptions.terminal.copyOnSelect",
          "description": "When true, copy selected terminal text to the system clipboard when the selection is committed. When false, cmux does not emit a Ghostty copy-on-select override; Ghostty config and defaults control selection-clipboard behavior."
        },
        "reflowHardWrapOnCopy": {
          "type": "boolean",
          "default": false,
          "description": "When true, copying terminal text also joins a line that exactly fills the terminal width onto the next line, undoing hard wraps a program inserted at the grid edge. Soft-wrapped rows are always joined."
        },
        "confirmUnsafePaste": {
          "type": "boolean",
          "default": false,
          "description": "When true, a paste that Ghostty's clipboard-paste-protection flags as unsafe (for example, text with a line break going to a program that has not enabled bracketed paste) waits for confirmation in a sheet attached to the terminal's window. When false, cmux pastes it without asking. OSC 52 clipboard reads are not affected."
        },
        "textEditingGestures": {
          "type": "boolean",
          "default": false,
          "description": "Replay macOS text-editing gestures as line-editor keys at the shell prompt: Command and Option arrow keys move by line and word, and Command and Option Delete kill by line and word. While a full-screen application (vim, less, htop, tmux) has the terminal on the alternate screen, it gets the keys as if gestures were off, unless textEditingGesturesInFullScreenApps is on. Ghostty's own bindings still apply there, so Command+Left sends Ctrl+A and Option+Left sends Esc b."
        },
        "textEditingCommandMovesByWord": {
          "type": "boolean",
          "default": false,
          "description": "With textEditingGestures on, switch to a browser-style layout: Command arrow and Delete keys move and delete by word, like Option, and Control+Left/Right move to the start and end of the line. Every other Control chord, including Ctrl+W and Ctrl+C, still reaches the terminal. macOS reserves Control+Left/Right for switching Spaces by default; turn those off in System Settings > Keyboard > Keyboard Shortcuts > Mission Control for Control+arrows to reach cmux."
        },
        "textEditingGesturesInFullScreenApps": {
          "type": "boolean",
          "default": false,
          "description": "Keep textEditingGestures active while a full-screen application has the terminal on the alternate screen. tmux, screen, and zellij keep the outer terminal on the alternate screen even at their shell prompt, so turn this on to use gestures inside a multiplexer. Applications that bind the gesture chords themselves then receive the translated keys."
        },
        "showPasswordInputIndicator": {
          "type": "boolean",
          "default": true,
          "description": "Show a lock badge in the terminal corner while the foreground program has turned echo off for a password prompt (sudo, ssh, passwd, gpg). cmux draws the badge itself and never changes terminal text. Only prompts on the local terminal are detected: an ssh password prompt counts, but sudo run inside an ssh session does not. Changes apply to an open prompt at once."
        },
        "showPasswordInputDots": {
          "type": "boolean",
          "default": false,
          "description": "When the password input badge is shown, also draw one dot per typed character. cmux keeps only a count, never the typed characters. Backspace removes a dot; Enter or echo turning back on clears them. Pasted text is not counted."
        },
        "autoResumeAgentSessions": {
          "type": "boolean",
          "default": true,
          "description": "Automatically run agent resume commands for restored terminal sessions when cmux reopens after quit. Set false to restore panes while keeping Claude Code, Codex, OpenCode, and other saved agent sessions idle until you resume them manually."
        },
        "showTextBoxOnNewTerminals": {
          "type": "boolean",
          "default": false,
          "descriptionKey": "schemaDescriptions.terminal.showTextBoxOnNewTerminals",
          "description": "Show the TextBox input by default for newly created workspaces, terminal tabs, and terminal splits."
        },
        "focusTextBoxOnNewTerminals": {
          "type": "boolean",
          "default": false,
          "descriptionKey": "schemaDescriptions.terminal.focusTextBoxOnNewTerminals",
          "description": "Focus the TextBox input by default for newly created workspaces, terminal tabs, and terminal splits. Focusing also shows the TextBox."
        },
        "agentHibernation": {
          "type": "object",
          "additionalProperties": false,
          "descriptionKey": "schemaDescriptions.terminal.agentHibernation",
          "description": "Routine Agent Hibernation settings. cmux kills idle background agent processes to free RAM and CPU, then resumes them with their saved session when their tab is visited. Routine hibernation requires a restorable coding agent whose lifecycle reports idle, an off-screen terminal, a live-terminal count above the configured limit, and unchanged output through the idle and confirmation windows. Independently, under memory pressure (critical pressure from macOS or from the cmux app's own footprint, or cmux's total memory use past its aggregate warning threshold) cmux may hibernate every safe idle background agent even when enabled is false; visible, running, needs-input, recently changed, and unprotectable agents remain excluded. The placeholder Resume button is a manual fallback.",
          "properties": {
            "enabled": {
              "type": "boolean",
              "default": false,
              "descriptionKey": "schemaDescriptions.terminal.agentHibernationEnabled",
              "description": "Enable routine Agent Hibernation based on the live-terminal limit. Memory-pressure safety hibernation remains active when false."
            },
            "idleSeconds": {
              "type": "integer",
              "minimum": 5,
              "maximum": 604800,
              "default": 5,
              "description": "Minimum seconds with no terminal output or input before an idle restorable agent terminal can hibernate. A short confirmation settle window (~60s) still applies on top of this before the agent is killed."
            },
            "maxLiveTerminals": {
              "type": "integer",
              "minimum": 1,
              "maximum": 256,
              "default": 12,
              "description": "Maximum live restorable agent terminals to keep before cmux hibernates eligible background terminals, oldest first."
            }
          }
        },
        "rendererRealization": {
          "type": "object",
          "additionalProperties": false,
          "description": "Reclaim off-screen terminal GPU renderer memory. cmux releases the Metal renderer (IOSurface) of a terminal that has stayed off-screen and idle while keeping its process and terminal state alive, then rebuilds the renderer instantly when the tab is visited again. Non-destructive and on by default.",
          "properties": {
            "enabled": {
              "type": "boolean",
              "default": true,
              "description": "Reclaim off-screen terminal renderer memory."
            },
            "idleSeconds": {
              "type": "integer",
              "minimum": 5,
              "maximum": 604800,
              "default": 5,
              "description": "Minimum seconds a terminal must stay off-screen before its GPU renderer memory is reclaimed."
            },
            "maxWarmRenderers": {
              "type": "integer",
              "minimum": 1,
              "maximum": 256,
              "default": 1,
              "description": "Most recently visible terminals to keep renderer-ready so switching stays instant. Extra off-screen renderers are reclaimed oldest first."
            }
          }
        },
        "textBoxMaxLines": {
          "type": "integer",
          "minimum": 1,
          "maximum": 20,
          "default": 10,
          "description": "Maximum number of lines the rich terminal TextBox input can grow to before it scrolls."
        },
        "textBoxDefaultSubmitAction": {
          "type": "string",
          "default": "text-entry",
          "description": "Default TextBox submit action ID for new terminal sessions. Use text-entry for plain input or one of the configured action IDs.",
          "descriptionKey": "schemaDescriptions.terminal.textBoxDefaultSubmitAction"
        },
        "textBoxSubmitActions": {
          "type": "array",
          "default": [],
          "description": "Configurable TextBox submit actions shown on the submit button, Shift-Tab cycle, and right-click menu.",
          "descriptionKey": "schemaDescriptions.terminal.textBoxSubmitActions",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["id", "title", "kind", "systemImage", "backgroundColorHex"],
            "properties": {
              "id": {
                "type": "string",
                "pattern": "^[A-Za-z0-9._-]+$",
                "description": "Stable action ID referenced by terminal.textBoxDefaultSubmitAction.",
                "descriptionKey": "schemaDescriptions.terminal.textBoxSubmitActionId"
              },
              "title": {
                "type": "string",
                "description": "Menu label for this submit action.",
                "descriptionKey": "schemaDescriptions.terminal.textBoxSubmitActionTitle"
              },
              "kind": {
                "type": "string",
                "enum": ["textEntry", "commandTemplate"],
                "description": "Whether this action submits plain Text Entry or expands a shell command template.",
                "descriptionKey": "schemaDescriptions.terminal.textBoxSubmitActionKind"
              },
              "commandTemplate": {
                "type": "string",
                "description": "Shell command template for commandTemplate actions. Include {{prompt}} to shell-quote the prompt into the command.",
                "descriptionKey": "schemaDescriptions.terminal.textBoxSubmitActionCommandTemplate"
              },
              "preservePromptAfterLaunch": {
                "type": "boolean",
                "description": "When true, launch commandTemplate without the prompt and keep the prompt in the TextBox for the active agent.",
                "descriptionKey": "schemaDescriptions.terminal.textBoxSubmitActionPreservePromptAfterLaunch"
              },
              "systemImage": {
                "type": "string",
                "description": "Fallback SF Symbol name shown on the submit button.",
                "descriptionKey": "schemaDescriptions.terminal.textBoxSubmitActionSystemImage"
              },
              "assetName": {
                "type": "string",
                "description": "Optional app asset catalog image name shown on the submit button.",
                "descriptionKey": "schemaDescriptions.terminal.textBoxSubmitActionAssetName"
              },
              "imagePath": {
                "type": "string",
                "description": "Optional PNG or image file path shown on the submit button. Tilde is expanded.",
                "descriptionKey": "schemaDescriptions.terminal.textBoxSubmitActionImagePath"
              },
              "backgroundColorHex": {
                "type": "string",
                "pattern": "^#?[0-9A-Fa-f]{6}([0-9A-Fa-f]{2})?$",
                "description": "Action color metadata as RGB or RGBA hex. The submit button fill stays white and only changes opacity between enabled and disabled states.",
                "descriptionKey": "schemaDescriptions.terminal.textBoxSubmitActionBackgroundColorHex"
              }
            },
            "allOf": [
              {
                "if": {
                  "required": ["kind"],
                  "properties": {
                    "kind": { "const": "commandTemplate" }
                  }
                },
                "then": {
                  "required": ["commandTemplate"],
                  "anyOf": [
                    {
                      "properties": {
                        "commandTemplate": {
                          "type": "string",
                          "pattern": "\\{\\{prompt\\}\\}"
                        }
                      }
                    },
                    {
                      "required": ["preservePromptAfterLaunch"],
                      "properties": {
                        "preservePromptAfterLaunch": { "const": true }
                      }
                    }
                  ]
                }
              }
            ]
          }
        },
        "resumeCommands": {
          "type": "array",
          "default": [],
          "description": "Signed command-prefix approvals for restoring non-agent terminal surfaces. cmux writes this list when you approve a surface resume command.",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["version", "id", "commandPrefix", "environmentKeys", "policy", "createdAt", "updatedAt", "signature"],
            "properties": {
              "version": {
                "type": "integer",
                "const": 1
              },
              "id": {
                "type": "string"
              },
              "name": {
                "type": "string"
              },
              "commandPrefix": {
                "type": "array",
                "minItems": 1,
                "items": {
                  "type": "string",
                  "minLength": 1
                },
                "description": "Shell argv prefix that must match the saved resume command."
              },
              "cwd": {
                "type": "string",
                "description": "Optional working directory that must match the saved resume command."
              },
              "environment": {
                "type": "object",
                "additionalProperties": {
                  "type": "string"
                },
                "description": "Optional non-sensitive environment values that must match the saved resume command."
              },
              "environmentKeys": {
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
              "source": {
                "type": "string"
              },
              "policy": {
                "type": "string",
                "enum": ["manual", "prompt", "auto"]
              },
              "createdAt": {
                "type": "number"
              },
              "updatedAt": {
                "type": "number"
              },
              "lastUsedAt": {
                "type": "number"
              },
              "signature": {
                "type": "string",
                "description": "HMAC signature for the record. Changing signed fields invalidates the approval."
              }
            }
          }
        },
        "uploadCommands": {
          "type": "array",
          "default": [],
          "description": "Host-scoped rules that replace the built-in scp for terminal file drops and pastes over SSH. When the ssh destination matches a rule, cmux runs that rule's command once per file instead of scp, and inserts the command's stdout at the cursor (verbatim, with control characters stripped); if the command prints nothing, cmux inserts the shell-escaped remote path it chose instead. Per-file outputs are space-joined. First matching enabled rule wins; no match runs the built-in scp unchanged. A non-zero exit, timeout, or cancel inserts nothing.",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["command"],
            "properties": {
              "hostPattern": {
                "type": ["string", "null"],
                "minLength": 1,
                "description": "fnmatch glob matched against the ssh destination (user@ and IPv6 brackets stripped, lowercased), like a single ssh_config Host pattern. When the session sets a HostName (for example through a ProxyCommand or broker), the rule also matches against that resolved host. Omit the key or set it to null for a catch-all (a blank string is rejected)."
              },
              "command": {
                "type": "string",
                "minLength": 1,
                "pattern": "\\S",
                "description": "Shell command run via /bin/sh -c, once per file. It receives the file and endpoint on its environment (CMUX_UPLOAD_LOCAL_PATH, CMUX_UPLOAD_REMOTE_PATH, CMUX_UPLOAD_DESTINATION, CMUX_UPLOAD_PORT, CMUX_UPLOAD_IDENTITY_FILE, CMUX_UPLOAD_SSH_OPTIONS). Its stdout is what cmux inserts at the cursor."
              },
              "enabled": {
                "type": "boolean",
                "default": true,
                "description": "Whether this rule is active. Defaults to true."
              }
            }
          }
        }
      }
    },
    "notifications": {
      "title": "notifications",
      "description": "Notification behavior from Settings > Notifications.",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "dockBadge": {
          "x-cmux-scopes": ["global"],
          "type": "boolean",
          "default": true,
          "description": "Show the unread count in the Dock tile."
        },
        "showInMenuBar": {
          "x-cmux-scopes": ["global"],
          "type": "boolean",
          "default": true,
          "description": "Show the menu bar extra."
        },
        "unreadPaneRing": {
          "x-cmux-scopes": ["global"],
          "type": "boolean",
          "default": true,
          "description": "Highlight panes with unread notifications."
        },
        "paneFlash": {
          "x-cmux-scopes": ["global"],
          "type": "boolean",
          "default": true,
          "description": "Flash the focused pane when requested."
        },
        "paneFlashColor": {
          "x-cmux-scopes": ["global"],
          "$ref": "#/$defs/colorHexOrNull",
          "default": null,
          "descriptionKey": "schemaDescriptions.notifications.paneFlashColor",
          "description": "Override the pane flash and unread ring color. Null keeps the built-in blue."
        },
        "soundWhenFocused": {
          "x-cmux-scopes": ["global"],
          "type": "boolean",
          "default": false,
          "descriptionKey": "schemaDescriptions.notifications.soundWhenFocused",
          "description": "Play the notification sound even when the pane that notified is already focused. Off by default, so a focused pane shows only its ring and flash."
        },
        "suppressOnlyFocusedSurface": {
          "x-cmux-scopes": ["global"],
          "type": "boolean",
          "default": false,
          "descriptionKey": "schemaDescriptions.notifications.suppressOnlyFocusedSurface",
          "description": "When enabled, a notification banner is auto-withdrawn only when its surface is the exact focused surface. A banner delivered for a non-focused surface in the currently visible workspace stays up until you focus that surface (or click/dismiss it), instead of being retracted when the workspace becomes visible. Off preserves the legacy workspace-visibility withdraw."
        },
        "suppressWhenAppFocused": {
          "x-cmux-scopes": ["global"],
          "type": "boolean",
          "default": false,
          "descriptionKey": "schemaDescriptions.notifications.suppressWhenAppFocused",
          "description": "When enabled, cmux skips the desktop banner for every notification while cmux is the active app, not only for the focused pane. Notifications still appear in the sidebar, the sound and custom command still run, and phone forwarding is unchanged. Off keeps showing banners for other workspaces and panes while cmux is focused."
        },
        "agentPermissionPrompt": {
          "x-cmux-scopes": ["global"],
          "type": "boolean",
          "default": true,
          "descriptionKey": "schemaDescriptions.notifications.agentPermissionPrompt",
          "description": "Notify when an agent (e.g. Claude Code) is blocked waiting for your permission to run a tool. On by default, since this is the alert you must act on to unblock the agent."
        },
        "agentTurnComplete": {
          "x-cmux-scopes": ["global"],
          "type": "string",
          "enum": ["whenIdle", "always", "never"],
          "default": "whenIdle",
          "descriptionKey": "schemaDescriptions.notifications.agentTurnComplete",
          "description": "When to notify that an agent finished a turn. whenIdle (default) suppresses the notification while the agent still has a running background task or a pending scheduled wakeup, so you are pinged once work truly drains. always notifies on every turn end; never disables it."
        },
        "agentIdleReminder": {
          "x-cmux-scopes": ["global"],
          "type": "boolean",
          "default": true,
          "descriptionKey": "schemaDescriptions.notifications.agentIdleReminder",
          "description": "Notify when an agent has been idle waiting for your input (about 60s after a turn ends). Suppressed while background work from the last turn is still pending, so a running build or watcher does not trigger a false waiting alert."
        },
        "sound": {
          "x-cmux-scopes": ["global"],
          "type": "string",
          "enum": [
            "default",
            "Basso",
            "Blow",
            "Bottle",
            "Frog",
            "Funk",
            "Glass",
            "Hero",
            "Morse",
            "Ping",
            "Pop",
            "Purr",
            "Sosumi",
            "Submarine",
            "Tink",
            "custom_file",
            "none"
          ],
          "default": "default",
          "description": "Notification sound preset."
        },
        "customSoundFilePath": {
          "x-cmux-scopes": ["global"],
          "type": "string",
          "default": "",
          "description": "Local path to the custom notification sound file."
        },
        "soundOverrides": {
          "x-cmux-scopes": ["global"],
          "type": "object",
          "default": {},
          "maxProperties": 256,
          "descriptionKey": "schemaDescriptions.notifications.soundOverrides",
          "description": "Sparse per-agent and per-alert-type notification sound overrides. Missing cells use notifications.sound.",
          "propertyNames": {
            "allOf": [
              { "pattern": "^[A-Za-z0-9._-]+$" },
              { "maxLength": 64 },
              { "not": { "enum": [".", ".."] } }
            ]
          },
          "patternProperties": {
            "^[A-Za-z0-9._-]+$": {
              "type": "object",
              "maxProperties": 3,
              "additionalProperties": false,
              "properties": {
                "turnDone": { "$ref": "#/$defs/notificationSoundOverride" },
                "needsInput": { "$ref": "#/$defs/notificationSoundOverride" },
                "errorStalled": { "$ref": "#/$defs/notificationSoundOverride" }
              }
            }
          },
          "additionalProperties": false
        },
        "command": {
          "x-cmux-scopes": ["global"],
          "type": "string",
          "default": "",
          "description": "Optional shell command to run alongside notification delivery."
        },
        "hooksMode": {
          "type": "string",
          "enum": ["append", "replace"],
          "default": "append",
          "description": "Controls whether project-local notification hooks append to inherited hooks or replace them."
        },
        "hooks": {
          "type": "array",
          "default": [],
          "description": "Composable shell hooks that receive notification policy JSON on stdin and return updated policy JSON on stdout.",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["id", "command"],
            "properties": {
              "id": {
                "type": "string",
                "minLength": 1,
                "description": "Stable hook identifier used in logs and failure alerts."
              },
              "command": {
                "type": "string",
                "minLength": 1,
                "pattern": ".*\\S.*",
                "description": "Shell command run with notification policy JSON on stdin."
              },
              "timeoutSeconds": {
                "type": "number",
                "exclusiveMinimum": 0,
                "default": 20,
                "description": "Maximum time cmux waits for this hook before falling back to default notification behavior."
              },
              "enabled": {
                "type": "boolean",
                "default": true,
                "description": "Disable this hook without removing it."
              }
            }
          }
        }
      }
    },
