        },
        "claudeCodeIntegration": {
          "type": "boolean",
          "default": true,
          "description": "Enable cmux integration hooks for Claude Code."
        },
        "codexIntegration": {"type": "boolean", "default": true, "description": "Enable cmux integration hooks for Codex. When disabled, cmux no longer wraps the codex command but still tracks live Codex sessions it can observe."},
        "piIntegration": {"type": "boolean", "default": true, "description": "Enable cmux integration hooks for Pi."},
        "claudeBinaryPath": {
          "type": "string",
          "default": "",
          "description": "Custom path to the claude binary."
        },
        "workspaceAutoNaming": {
          "type": "boolean",
          "default": false,
          "descriptionKey": "schemaDescriptions.automation.workspaceAutoNaming",
          "description": "Opt-in AI auto-naming of workspaces and tabs from agent conversation content. When enabled, cmux summarizes supported agent sessions into short titles using each agent's own binary; manual renames always win."
        },
        "autoNamingAgent": {
          "type": "string",
          "default": "auto",
          "descriptionKey": "schemaDescriptions.automation.autoNamingAgent",
          "description": "Which agent generates auto-names for every session. \"auto\" (default) names each session with its own agent; any agent slug (claude, codex, grok, opencode, pi, omp, …) overrides naming for all sessions, even other agents' sessions. Undriveable or uninstalled agents fall back to the session's own agent, so naming never breaks."
        },
        "ripgrepBinaryPath": {
          "type": "string",
          "default": "",
          "description": "Custom path to the ripgrep (rg) binary used by project search."
        },
        "suppressSubagentNotifications": {
          "type": "boolean",
          "default": true,
          "descriptionKey": "schemaDescriptions.automation.suppressSubagentNotifications",
          "description": "Suppress visible completion notifications and status mutations from nested Codex or Claude child agents while keeping their events in Feed telemetry."
        },
        "ampIntegration": {
          "type": "boolean",
          "default": true,
          "descriptionKey": "schemaDescriptions.automation.ampIntegration",
          "description": "Enable cmux integration hooks for Amp. When disabled, the bundled plugin stays inactive without needing to be removed."
        },
        "cursorIntegration": {
          "type": "boolean",
          "default": true,
          "description": "Enable cmux integration hooks for Cursor."
        },
        "geminiIntegration": {
          "type": "boolean",
          "default": true,
          "description": "Enable cmux integration hooks for Gemini."
        },
        "kiroIntegration": {
          "type": "boolean",
          "default": true,
          "description": "Enable cmux integration hooks for Kiro CLI."
        },
        "kiroNotificationLevel": {
          "type": "string",
          "enum": [
            "minimal",
            "standard",
            "verbose"
          ],
          "default": "standard",
          "description": "Controls how many Kiro tool events appear in Feed."
        },
        "portBase": {
          "type": "integer",
          "minimum": 1,
          "default": 9100,
          "description": "Starting value for workspace CMUX_PORT assignments."
        },
        "portRange": {
          "type": "integer",
          "minimum": 1,
          "default": 10,
          "description": "Number of ports reserved per workspace."
        }
      }
