  "$defs": {
    "colorHex": {
      "type": "string",
      "pattern": "^#[0-9A-Fa-f]{6}$",
      "description": "Uppercase or lowercase 6-digit hex color."
    },
    "colorHexOrNull": {
      "oneOf": [
        {
          "$ref": "#/$defs/colorHex"
        },
        {
          "type": "null"
        }
      ]
    },
    "notificationSoundOverride": {
      "oneOf": [
        {
          "type": "object",
          "additionalProperties": false,
          "required": ["sound"],
          "properties": {
            "sound": {
              "type": "string",
              "enum": ["default", "Basso", "Blow", "Bottle", "Frog", "Funk", "Glass", "Hero", "Morse", "Ping", "Pop", "Purr", "Sosumi", "Submarine", "Tink", "none"]
            }
          }
        },
        {
          "type": "object",
          "additionalProperties": false,
          "required": ["sound", "customSoundFilePath"],
          "properties": {
            "sound": { "const": "custom_file" },
            "customSoundFilePath": {
              "type": "string",
              "minLength": 1,
              "pattern": ".*\\S.*"
            }
          }
        }
      ],
      "descriptionKey": "schemaDescriptions.notifications.soundOverride",
      "description": "A notification sound override. `default` uses notifications.sound, `none` disables playback, and the remaining values select a built-in or custom sound."
    },
    "shortcutBinding": {
      "oneOf": [
        {
          "$ref": "#/$defs/unboundShortcutBinding",
          "description": "Unbind this shortcut. Accepted values are an empty string, none, clear, unbound, or disabled."
        },
        {
          "$ref": "#/$defs/shortcutFirstStroke",
          "description": "Single-stroke shortcut, for example cmd+n or cmd+space."
        },
        {
          "type": "array",
          "minItems": 1,
          "maxItems": 2,
          "prefixItems": [
            {
              "$ref": "#/$defs/shortcutFirstStroke"
            },
            {
              "$ref": "#/$defs/shortcutStroke"
            }
          ],
          "description": "Chorded shortcut. Example: [\"ctrl+b\", \"c\"]."
        }
      ]
    },
    "shortcutBindingNullable": {
      "oneOf": [
        {
          "$ref": "#/$defs/shortcutBinding"
        },
        {
          "type": "null",
          "description": "Unbind this shortcut."
        }
      ]
    },
    "singleBareFirstStrokeShortcutBinding": {
      "oneOf": [
        {
          "$ref": "#/$defs/unboundShortcutBinding",
          "description": "Unbind this shortcut. Accepted values are an empty string, none, clear, unbound, or disabled."
        },
        {
          "$ref": "#/$defs/bareFirstStrokeShortcutFirstStroke",
          "description": "Single-stroke shortcut. Bare first strokes are accepted for this action."
        }
      ]
    },
    "singleBareFirstStrokeShortcutBindingNullable": {
      "oneOf": [
        {
          "$ref": "#/$defs/singleBareFirstStrokeShortcutBinding"
        },
        {
          "type": "null",
          "description": "Unbind this shortcut."
        }
      ]
    },
    "bareFirstStrokeShortcutBinding": {
      "oneOf": [
        {
          "$ref": "#/$defs/unboundShortcutBinding",
          "description": "Unbind this shortcut. Accepted values are an empty string, none, clear, unbound, or disabled."
        },
        {
          "$ref": "#/$defs/bareFirstStrokeShortcutFirstStroke",
          "description": "Single-stroke shortcut. Bare first strokes are accepted for this action."
        },
        {
          "type": "array",
          "minItems": 1,
          "maxItems": 2,
          "prefixItems": [
            {
              "$ref": "#/$defs/bareFirstStrokeShortcutFirstStroke"
            },
            {
              "$ref": "#/$defs/shortcutStroke"
            }
          ],
          "description": "Chorded shortcut. Bare first strokes are accepted for this action. Example: [\"g\", \"g\"]."
        }
      ]
    },
    "bareFirstStrokeShortcutBindingNullable": {
      "oneOf": [
        {
          "$ref": "#/$defs/bareFirstStrokeShortcutBinding"
        },
        {
          "type": "null",
          "description": "Unbind this shortcut."
        }
      ]
    },
    "unboundShortcutBinding": {
      "type": "string",
      "enum": ["", "none", "clear", "unbound", "disabled"]
    },
    "shortcutFirstStroke": {
      "allOf": [
        {
          "$ref": "#/$defs/shortcutStroke"
        },
        {
          "anyOf": [
            {
              "pattern": "^(?:(?:[cC][mM][dD]|[cC][oO][mM][mM][aA][nN][dD]|[sS][hH][iI][fF][tT]|[oO][pP][tT]|[oO][pP][tT][iI][oO][nN]|[aA][lL][tT]|[cC][tT][rR][lL]|[cC][oO][nN][tT][rR][oO][lL]|[cC][tT][lL]|⌘|⇧|⌥|⌃)\\+)+"
            },
            {
              "pattern": "^(?: |[sS][pP][aA][cC][eE]|[sS][pP][aA][cC][eE][bB][aA][rR]|<[sS][pP][aA][cC][eE]>)$"
            }
          ]
        }
      ],
      "description": "First or only shortcut stroke. Must include a modifier unless the key is Space."
    },
    "bareFirstStrokeShortcutFirstStroke": {
      "allOf": [
        {
          "$ref": "#/$defs/shortcutStroke"
        },
        {
          "anyOf": [
            {
              "pattern": "^(?:(?:[cC][mM][dD]|[cC][oO][mM][mM][aA][nN][dD]|[sS][hH][iI][fF][tT]|[oO][pP][tT]|[oO][pP][tT][iI][oO][nN]|[aA][lL][tT]|[cC][tT][rR][lL]|[cC][oO][nN][tT][rR][oO][lL]|[cC][tT][lL]|⌘|⇧|⌥|⌃)\\+)+"
            },
            {
              "pattern": "^(?: |[sS][pP][aA][cC][eE]|[sS][pP][aA][cC][eE][bB][aA][rR]|<[sS][pP][aA][cC][eE]>)$"
            },
            {
              "pattern": "^(?:[rR][eE][tT][uU][rR][nN]|[eE][nN][tT][eE][rR]|↩)$"
            },
            {
              "pattern": "^(?:[lL][eE][fF][tT]|[aA][rR][rR][oO][wW][lL][eE][fF][tT]|[lL][eE][fF][tT][aA][rR][rR][oO][wW]|←|[rR][iI][gG][hH][tT]|[aA][rR][rR][oO][wW][rR][iI][gG][hH][tT]|[rR][iI][gG][hH][tT][aA][rR][rR][oO][wW]|→|[uU][pP]|[aA][rR][rR][oO][wW][uU][pP]|[uU][pP][aA][rR][rR][oO][wW]|↑|[dD][oO][wW][nN]|[aA][rR][rR][oO][wW][dD][oO][wW][nN]|[dD][oO][wW][nN][aA][rR][rR][oO][wW]|↓)$"
            },
            {
              "pattern": "^(?:[A-Za-z0-9]|[,./\\\\;'`=\\[\\]-]|[cC][oO][mM][mM][aA]|[pP][eE][rR][iI][oO][dD]|[dD][oO][tT]|[sS][lL][aA][sS][hH]|[bB][aA][cC][kK][sS][lL][aA][sS][hH]|[sS][eE][mM][iI][cC][oO][lL][oO][nN]|[qQ][uU][oO][tT][eE]|[aA][pP][oO][sS][tT][rR][oO][pP][hH][eE]|[bB][aA][cC][kK][tT][iI][cC][kK]|[gG][rR][aA][vV][eE]|[mM][iI][nN][uU][sS]|[hH][yY][pP][hH][eE][nN]|[pP][lL][uU][sS]|[eE][qQ][uU][aA][lL][sS]|[lL][eE][fF][tT][bB][rR][aA][cC][kK][eE][tT]|[oO][pP][eE][nN][bB][rR][aA][cC][kK][eE][tT]|[rR][iI][gG][hH][tT][bB][rR][aA][cC][kK][eE][tT]|[cC][lL][oO][sS][eE][bB][rR][aA][cC][kK][eE][tT])$"
            }
          ]
        }
      ],
      "description": "First or only shortcut stroke. Bare printable keys are accepted for actions that opt into bare first strokes."
    },
    "shortcutStroke": {
